<?php
declare(strict_types=1);
namespace DLoop\StagingDiagnostic;

// Private CLI only. No application bootstrap, DB/admin tools, network or writes.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
ini_set('display_errors', '0');
ini_set('display_startup_errors', '0');
ini_set('log_errors', '0');
$stage = 'RUNTIME';
$resultSent = false;
$bufferLevel = ob_get_level();
ob_start(static fn(string $buffer): string => '');
$finish = static function (string $code, int $status) use (&$resultSent, $bufferLevel): never {
    $resultSent = true;
    while (ob_get_level() > $bufferLevel) ob_end_clean();
    echo $code, "\n";
    exit($status);
};
register_shutdown_function(static function () use (&$resultSent, &$stage, $bufferLevel): void {
    if ($resultSent) return;
    while (ob_get_level() > $bufferLevel) ob_end_clean();
    echo 'FAIL: ', $stage, "\n";
});
set_error_handler(static function (): never { throw new \RuntimeException(); });
try {
    if (PHP_VERSION_ID < 80300 || PHP_INT_SIZE !== 8
        || !function_exists('json_decode') || !function_exists('preg_match')
        || !function_exists('putenv') || !function_exists('fileowner')) throw new \RuntimeException();
    $stage = 'INVOCATION';
    if (!isset($argv) || count($argv) !== 1) throw new \RuntimeException();
    $stage = 'CONFIGURATION_PATH';
    $root = realpath(dirname(__DIR__));
    if (!$root || !is_dir($root)) throw new \RuntimeException();
    $config = realpath($root.'/config.local.php');
    $secretsDirectory = realpath($root.'/secrets');
    $secret = realpath($root.'/secrets/staging-secrets.json');
    $inside = static fn(string $file, string $directory): bool => str_starts_with(
        str_replace('\\', '/', $file), rtrim(str_replace('\\', '/', $directory), '/').'/');
    if (!$config || !$secretsDirectory || !$secret || !is_file($config) || !is_readable($config)
        || !is_dir($secretsDirectory) || !is_file($secret) || !is_readable($secret)
        || !$inside($config, $root) || !$inside($secretsDirectory, $root) || !$inside($secret, $root)) throw new \RuntimeException();
    $publicRoots = [];
    foreach (['/home4/dltsin/public_html', $_SERVER['DOCUMENT_ROOT'] ?? '', $root.'/public'] as $candidate) {
        if ($candidate === '') continue;
        $public = realpath($candidate);
        if (!$public) continue;
        $publicRoots[] = $public;
        foreach ([$root, $config, $secretsDirectory, $secret] as $private) {
            if ($private === $public || $inside($private, $public)) throw new \RuntimeException();
        }
    }
    // Require POSIX-style protection even when a local test host models metadata.
    $privatePaths = [$root, $config, $secretsDirectory, $secret];
    $stage = 'PRIVATE_OWNERSHIP';
    $owner = fileowner($config);
    if ($owner === false) throw new \RuntimeException();
    foreach ($privatePaths as $private) if (fileowner($private) !== $owner) throw new \RuntimeException();
    $stage = 'PRIVATE_PERMISSIONS';
    foreach ($privatePaths as $private) {
        $mode = fileperms($private);
        if ($mode === false || ($mode & 0077) !== 0) throw new \RuntimeException();
    }
    $stage = 'JSON_READ';
    $bytes = file_get_contents($secret, false, null, 0, 8193);
    if (!is_string($bytes) || strlen($bytes) > 8192) throw new \RuntimeException();
    $stage = 'JSON_SYNTAX';
    $values = json_decode($bytes, true, 8, JSON_THROW_ON_ERROR);
    unset($bytes);
    $stage = 'JSON_SCHEMA';
    if (!is_array($values) || count($values) !== 2 || !isset($values['databasePassword'], $values['appKey'])
        || !is_string($values['databasePassword']) || $values['databasePassword'] === ''
        || !is_string($values['appKey']) || strlen($values['appKey']) < 32
        || str_contains($values['databasePassword'], "\0") || str_contains($values['appKey'], "\0")) throw new \RuntimeException();
    unset($values);
    $stage = 'SESSION_DIRECTORY';
    $sessions = realpath($root.'/var/sessions');
    if (!$sessions || !is_dir($sessions) || !is_writable($sessions)) throw new \RuntimeException();
    foreach ($publicRoots as $public) if ($sessions === $public || $inside($sessions, $public)) throw new \RuntimeException();
    $stage = 'CONFIGURATION_VERSION';
    // Exact reviewed nonsecret code, not secret hashes. Never eval these references.
    $approved = [
        'config.local.php'=>'',
        'src/Config.php'=>'',
        'src/LocalAccess.php'=>''
    ];
    foreach ($approved as $relative => $encoded) {
        $file = realpath($root.'/'.$relative);
        if (!$file || !$inside($file, $root) || !is_file($file) || !is_readable($file)) throw new \RuntimeException();
        $source = file_get_contents($file, false, null, 0, 65537);
        if (!is_string($source) || strlen($source) > 65536) throw new \RuntimeException();
        $references=[base64_decode($encoded,true)];
        if($relative==='config.local.php'){
            // Exact previously reviewed template, with only its explicit Wi-Fi boolean selectable.
            $legacy=base64_decode('',true);
            $references[]=$legacy;
            $references[]=str_replace("'wifi_scale_enabled'=>false,", "'wifi_scale_enabled'=>true,", $legacy);
        }
        $normalized=str_replace("\$profile = 'wifi-enabled';", "\$profile = 'disabled';", str_replace("\r\n", "\n", $source));
        if(!in_array($normalized,$references,true))throw new \RuntimeException();
    }
    $stage = 'CONFIGURATION_LOAD';
    if (!putenv('DLOOP_CONFIG_FILE='.$config)) throw new \RuntimeException();
    require_once $root.'/src/LocalAccess.php';
    require_once $root.'/src/Config.php';
    $c = \DLoop\Config::load($root);
    // Legacy reviewed file-backed configs have an explicit boolean but no profile key.
    $profile=array_key_exists('staging_wifi_profile',$c)?$c['staging_wifi_profile']:(($c['wifi_scale_enabled']??null)===true?'wifi-enabled':'disabled');
    $stage = 'STAGING_IDENTITY';
    if ($c['environment'] !== 'production' || $c['access_mode'] !== 'AUTHENTICATED'
        || $c['allowed_origins'] !== ['https://staging-fila.dlts.in']
        || ($c['phone_nfc_origin'] ?? null) !== 'https://staging-fila.dlts.in'
        || $c['database']['name'] !== 'dltsin_fila_stage' || $c['database']['user'] !== 'dltsin_fila_stage'
        || $c['database']['host'] !== 'localhost' || $c['database']['port'] !== 3306
        || (!in_array($profile, ['disabled','wifi-enabled'], true) || ($c['wifi_scale_enabled'] ?? null) !== (($profile) === 'wifi-enabled'))) throw new \RuntimeException();
    unset($c);
    $stage = 'UNEXPECTED_OUTPUT';
    if (ob_get_length() !== 0) throw new \RuntimeException();
    $finish('PASS: STAGING_CONFIGURATION', 0);
} catch (\Throwable $e) {
    $finish('FAIL: '.$stage, 1);
}
